function normalizeArabicText(str) {
  if (!str) return '';
  return str
    .replace(/[–—_\-\/\\()\[\]«»""'']/g, ' ')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/[ًٌٍَُِّْ]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function findIasjJournal(query) {
  if (!query || typeof query !== 'string') return null;
  const qNorm = normalizeArabicText(query);
  if (!qNorm) return null;

  if (typeof IASJ_MASTER_JOURNALS === 'undefined' || !Array.isArray(IASJ_MASTER_JOURNALS)) {
    return null;
  }

  // 1. مطابقة تامة بعد المعالجة
  let found = IASJ_MASTER_JOURNALS.find(j => 
    normalizeArabicText(j.ar) === qNorm || normalizeArabicText(j.en) === qNorm
  );
  if (found) return { journal: found, matchType: 'exact', directUrl: 'https://iasj.mohesr.gov.iq/journals/journal/view/' + found.id };

  // 2. مطابقة العنوان الرئيسي النظيف بدون لاحقة الجامعة (مثال: 'مجلة كلية التربية' مع 'مجلة كلية التربية - جامعة واسط')
  found = IASJ_MASTER_JOURNALS.find(j => {
    const arClean = normalizeArabicText(j.ar.split('-')[0].trim());
    const enClean = normalizeArabicText(j.en.split('-')[0].trim());
    return (qNorm.length >= 6 && (arClean === qNorm || enClean === qNorm)) ||
           (qNorm.length >= 10 && (arClean.includes(qNorm) || enClean.includes(qNorm)));
  });
  if (found) return { journal: found, matchType: 'title_match', directUrl: 'https://iasj.mohesr.gov.iq/journals/journal/view/' + found.id };

  // 3. مطابقة الكلمات المفتاحية الذكية مع استبعاد الكلمات العامة الشائعة
  const stopWords = new Set([
    'مجله', 'جامعه', 'كليه', 'للعلوم', 'علوم', 'العراقيه', 'عراقي', 'دوريه', 'دراسات', 'بحوث', 'ابحاث', 'العلميه',
    'journal', 'journals', 'of', 'university', 'college', 'for', 'the', 'and', 'in', 'international', 
    'research', 'researches', 'studies', 'review', 'applied', 'academic', 'academy', 'science', 'sciences', 'scientific'
  ]);
  const tokens = qNorm.split(' ').filter(w => w.length > 2 && !stopWords.has(w));

  if (tokens.length >= 1) {
    let best = null;
    let maxMatches = 0;

    for (const j of IASJ_MASTER_JOURNALS) {
      const jTokens = new Set(normalizeArabicText(j.ar + ' ' + j.en).split(' '));
      let matches = 0;
      for (const t of tokens) {
        if (jTokens.has(t)) matches++;
      }
      if (matches > maxMatches) {
        maxMatches = matches;
        best = j;
      }
    }

    // إذا كانت كلمة مفردة خاصة جداً (مثل الفراهيدي أو دجلة أو المستنصرية بطول 5 أحرف فأكثر)
    if (best && tokens.length === 1 && maxMatches === 1 && tokens[0].length >= 5) {
      return { journal: best, matchType: 'fuzzy_single', directUrl: 'https://iasj.mohesr.gov.iq/journals/journal/view/' + best.id };
    }
    // إذا كانت عدة كلمات: تتطلب تطابق كلمتين على الأقل ونسبة تطابق 50% فأكثر من الكلمات الخاصة
    if (best && maxMatches >= 2 && (maxMatches / tokens.length) >= 0.5) {
      return { journal: best, matchType: 'fuzzy', directUrl: 'https://iasj.mohesr.gov.iq/journals/journal/view/' + best.id };
    }
  }

  return null;
}
